<script setup lang="ts">import {onBeforeUnmount,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore(),router=useRouter(),route=useRoute(),open=ref(false),notice=ref('');const admin=[['/admin/dashboard','📊','Dashboard Monitoring'],['/admin/berkas','📁','Verifikasi E-Berkas'],['/admin/pegawai','👥','Master Data Pegawai'],['/admin/laporan','📥','Ekspor Laporan'],['/admin/audit-log','🧾','Audit Log']];const pegawai=[['/pegawai/dashboard','👤','Profil & E-Berkas']];function logout(){auth.logout();router.push('/login')}function forbidden(e:Event){notice.value=(e as CustomEvent).detail;setTimeout(()=>notice.value='',5000)}onMounted(()=>window.addEventListener('sikapj:forbidden',forbidden));onBeforeUnmount(()=>window.removeEventListener('sikapj:forbidden',forbidden));</script>
